answer = ifScript();

function ifScript() {
	const ga_role = new GlideAggregate('x_xal_idconnect_isc_access_item');
	ga_role.addAggregate('COUNT', 'owner');
	ga_role.addEncodedQuery('sys_idIN' + current.variables.isc_access_item_lc);

	ga_role.query();

	let rowcount = 0;

	while (ga_role.next()) {
		if (rowcount == 0) {
			current.variables.owner = ga_role.getValue('owner');
		}
		rowcount++;
	}
	if (ga_role.getRowCount() > 1) {
		return 'yes';
	}
	else
		return 'no';
}

