const ga_role = new GlideAggregate('x_xal_idconnect_isc_access_item');
ga_role.addAggregate('COUNT', 'owner');
ga_role.addEncodedQuery('sys_idIN' + current.variables.isc_access_item_lc);

ga_role.query();

let role_collection = [];

while (ga_role.next()) {
	const gr_role = new GlideRecord('x_xal_idconnect_isc_access_item');
	if (ga_role.getValue('owner') == '') {
		gr_role.addEncodedQuery('sys_idIN' + current.variables.isc_access_item_lc + '^owner=NULL');
	}
	else {
		gr_role.addEncodedQuery('sys_idIN' + current.variables.isc_access_item_lc + '^owner=' + ga_role.getValue('owner'));
	}
	gr_role.query();

	let roles = [];
	while (gr_role.next()) {
		roles.push(gr_role.sys_id.toString());
	}
	role_collection.push({
		"owner": ga_role.getValue('owner'),
		"roles": roles.toString()
	});
}

workflow.info(`role_collection object - \r\n\r\n ${JSON.stringify(role_collection)}`);

for (var i = 1;i < role_collection.length; i++) {
	createAdditionalRequest(role_collection[i].owner,role_collection[i].roles);
}

workflow.info(`Role Owner is ${role_collection[0].owner} and roles are ${role_collection[0].roles}`);
current.variables.owner = role_collection[0].owner.toString();
current.variables.isc_access_item_lc = role_collection[0].roles.toString();

function createAdditionalRequest(owner,roles) {
	const cart_id = `${gs.generateGUID()}:${current.cat_item.sys_id.toString()}:${current.requested_for.sys_id.toString()}`;
	const cart = new sn_sc.CartJS(cart_id);
	cart.setRequestedFor(current.requested_for.sys_id.toString());

	const cart_details = cart.addToCart({
		"sysparm_id": current.cat_item.toString(),
		"sysparm_quantity": '1',
		"variables": {
			"owner": owner,
			"isc_access_item_lc": roles,
			"new_owner": current.variables.new_owner.sys_id.toString()
		}
	});

	const request_details = cart.submitOrder({
		"requested_for": current.requested_for.sys_id.toString()
	});
	const gr_request = new GlideRecord('sc_request');
	gr_request.get(request_details.request_id);
	gr_request.opened_by = current.variables.opened_by;
	gr_request.update();
	
	workflow.info(JSON.stringify(request_details));

}

