// Set the variable 'answer' to '', 'approved' or 'rejected' to indicate the approval status for this approval.  When called, the following information is available:
//
//    counts.total = total number of users that are part of this approval
//    counts.approved = # of users that approved so far
//    counts.rejected = # of users that rejected so far
//    counts.requested = # of users that are pending approval
//    counts.not_requested = # of users that are not pending approval
//    counts.not_required = # of users that approval is not required
//

answer = [];

if (current.variables.owner.active && current.requested_for != current.variables.owner) {
	answer.push(current.variables.owner.toString());
}

if (current.variables.owner == current.requested_for && current.variables.owner.active) {
	current.work_notes = 'Skipping approval since current owner has requested change';
}

if (!current.variables.owner.active && current.variables.owner.manager.active) {
	answer.push(current.variables.owner.manager.toString());
}

if (!current.variables.owner.active && !current.variables.owner.manager.active && gs.getProperty('x_xal_idconnect.approval_fallback_group')) {
	workflow.info(`No valid approvers found... assigning approval to the group ${gs.getProperty('x_xal_idconnect.approval_fallback_group')}`);
	const gr_group = new GlideRecord('sys_user_grmember');
	gr_group.addEncodedQuery(`group.name=${gs.getProperty('x_xal_idconnect.approval_fallback_group')}`);

	gr_group.query();
	while (gr_group.next()) {
		answer.push(gr_group.user.getValue());
	}
}

