try {
	const roles = current.variables.isc_access_item_lc.toString().split(',');

	for (const role of roles) {
		const gr_role = new GlideRecord('x_xal_idconnect_isc_access_item');
		gr_role.get(role);
		workflow.info(`Updating entitlement id ${gr_role.sailpoint_id.toString()} with new owner ${current.variables.new_owner_identity_id.toString()}`);
		updateAccessItemOwner(gr_role.sailpoint_id.toString(), gr_role.getValue('sailpoint_object_type'), current.variables.new_owner_identity_id.toString());
	}
	activity.result = 'success';
}
catch (exception) {
	activity.result = 'failure';
}


function updateAccessItemOwner(item_id, item_type, identity_id) {
	const access_token = new x_xal_idconnect.XalientUtilitiesCore().getToken();
	const rm_patch = new sn_ws.RESTMessageV2('SailPoint ISC', `${item_type}-patch`);
	rm_patch.setStringParameterNoEscape('tenant', gs.getProperty('x_xal_idconnect.isc_tenant'));
	rm_patch.setStringParameterNoEscape('domain', gs.getProperty('x_xal_idconnect.domain'));
	rm_patch.setStringParameterNoEscape(`${item_type}_id`, item_id);
	rm_patch.setStringParameterNoEscape('identity_id', identity_id);
	rm_patch.setRequestHeader('Authorization', 'Bearer ' + access_token);

	const res_patch = rm_patch.execute();

	workflow.info(`Patch ${item_type} Call\r\n\r\nStatus Code - ${res_patch.getStatusCode()} - Response Body - \r\n\r\n ${res_patch.getBody()}`);
}

